<script setup lang="ts">
import { computed, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
const route = useRoute(); const router = useRouter(); const code = ref(""); const email = ref(""); const password = ref(""); const sent = ref(false); const submitted = ref(false);
const mode = computed(() => route.path.includes("/verify") ? "verify" : route.path.includes("/reset") ? "reset" : "request");
function next() { if (mode.value === "request") { sent.value = true; } else if (mode.value === "verify") router.push({ path: "/login/recovery/reset", query: { transaction: "pending" } }); else submitted.value = true; }
</script>
<template><main class="min-h-screen flex items-center justify-center bg-[var(--el-bg-color-page)] p-6"><el-card shadow="never" class="w-full max-w-md"><div class="mb-6"><h1 class="text-2xl font-semibold">{{ mode === 'request' ? '账号恢复' : mode === 'verify' ? '恢复验证' : '重设密码' }}</h1><p class="mt-2 text-sm text-[var(--el-text-color-secondary)]">{{ mode === 'request' ? '输入注册邮箱，我们会发送一次性恢复验证码。' : mode === 'verify' ? '请输入发送到邮箱的验证码。' : '设置新的登录密码，提交后请重新登录。' }}</p></div><el-alert v-if="submitted" title="密码已重设，请返回登录" type="success" show-icon :closable="false"/><el-form v-else label-position="top" @submit.prevent="next"><el-form-item v-if="mode === 'request'" label="邮箱" required><el-input v-model="email" type="email" autocomplete="email"/></el-form-item><el-form-item v-if="mode === 'verify'" label="验证码" required><el-input v-model="code" maxlength="8" autocomplete="one-time-code"/></el-form-item><template v-if="mode === 'reset'"><el-form-item label="新密码" required><el-input v-model="password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="确认新密码" required><el-input type="password" show-password autocomplete="new-password"/></el-form-item></template><el-alert v-if="sent" title="如果邮箱存在，验证码将发送到该邮箱" type="info" :closable="false" class="mb-4"/><el-button type="primary" class="w-full" native-type="submit">{{ mode === 'request' ? '发送验证码' : mode === 'verify' ? '验证并继续' : '确认重设' }}</el-button></el-form><el-button text class="mt-4 w-full" @click="router.push('/login')">返回登录</el-button></el-card></main></template>
